sys_script_include.script:
var ClaudePromptEvaluator = Class.create();
ClaudePromptEvaluator.prototype = {
    initialize: function() {},

    // ─── Template renderer ────────────────────────────────────────────────────
    /**
     * Replace {key} placeholders in a template string with values from a plain object.
     * Double braces {{ }} are left-unescaped to a single brace after substitution.
     * @param {string} template
     * @param {Object} vars  - plain key/value map
     * @returns {string}
     */
    render: function(template, vars) {
        var result = template;
        for (var key in vars) {
            if (vars.hasOwnProperty(key)) {
                result = result.split('{' + key + '}').join(String(vars[key]));
            }
        }
        return result.split('{{').join('{').split('}}').join('}');
    },

    // ─── Dataset generation ───────────────────────────────────────────────────
    /**
     * Ask Claude to generate N unique scenario ideas for a given task.
     * @param {string} taskDescription
     * @param {Object} promptInputsSpec  - { key: description, ... }
     * @param {number} numCases
     * @returns {Array<string>}  - array of idea strings
     */
    generateUniqueIdeas: function(taskDescription, promptInputsSpec, numCases) {
        var connector = new x_146833_claudec_0.ClaudeConnector();

        var inputsStr = '';
        for (var k in promptInputsSpec) {
            if (promptInputsSpec.hasOwnProperty(k)) {
                inputsStr += '"' + k + '": str # ' + promptInputsSpec[k] + ',';
            }
        }

        var prompt = this.render(
            'Generate {num_cases} unique, diverse ideas for testing a prompt that accomplishes this task:\n\n' +
            '<task_description>\n{task_description}\n</task_description>\n\n' +
            'The prompt will receive the following inputs:\n<prompt_inputs>\n{prompt_inputs}\n</prompt_inputs>\n\n' +
            'Each idea should represent a distinct scenario. Output a JSON array of idea strings.\n' +
            'Example: ["Idea one", "Idea two"]\n\nGenerate exactly {num_cases} ideas.',
            {
                task_description: taskDescription,
                num_cases:        numCases,
                prompt_inputs:    inputsStr
            }
        );

        var messages = [
            { role: 'user',      content: prompt },
            { role: 'assistant', content: '```json' }
        ];

        var result = connector.chat(messages, {
            system_prompt:  'You are a test scenario designer creating diverse, unique testing scenarios.',
            stop_sequences: ['```'],
            temperature:    1.0
        });

        if (!result.success) { return []; }
        try { return JSON.parse(result.text); } catch(e) { return []; }
    },

    /**
     * Ask Claude to generate a single test case object from an idea.
     * @param {string} taskDescription
     * @param {string} idea
     * @param {Object} promptInputsSpec
     * @returns {Object|null}  - { prompt_inputs, solution_criteria, task_description, scenario }
     */
    generateTestCase: function(taskDescription, idea, promptInputsSpec) {
        var connector = new x_146833_claudec_0.ClaudeConnector();

        var exampleInputs = '';
        var allowedKeys   = [];
        for (var k in promptInputsSpec) {
            if (promptInputsSpec.hasOwnProperty(k)) {
                exampleInputs += '"' + k + '": "EXAMPLE_VALUE", // ' + promptInputsSpec[k] + '\n';
                allowedKeys.push('"' + k + '"');
            }
        }
        var allowedKeysStr = allowedKeys.join(', ');

        var prompt = this.render(
            'Generate a single detailed test case for:\n\n' +
            '<task_description>\n{task_description}\n</task_description>\n\n' +
            '<specific_idea>\n{idea}\n</specific_idea>\n\n' +
            'Only use these input keys: {allowed_keys}\n\n' +
            'Output format:\n```json\n' +
            '{\n  "prompt_inputs": {\n    {example_inputs}  },\n' +
            '  "solution_criteria": ["criterion 1", "criterion 2"]\n}\n```\n\n' +
            'Requirements:\n- Only include the exact allowed keys\n' +
            '- 1 to 4 concise, measurable solution criteria\n' +
            '- Criteria must ONLY address the core task requirements\n' +
            '- Output should be solvable in under 400 tokens',
            {
                task_description: taskDescription,
                idea:             idea,
                allowed_keys:     allowedKeysStr,
                example_inputs:   exampleInputs
            }
        );

        var messages = [
            { role: 'user',      content: prompt },
            { role: 'assistant', content: '```json' }
        ];

        var result = connector.chat(messages, {
            system_prompt:  'You are a test case creator specializing in designing evaluation scenarios.',
            stop_sequences: ['```'],
            temperature:    0.7
        });

        if (!result.success) { return null; }
        try {
            var tc = JSON.parse(result.text);
            tc.task_description = taskDescription;
            tc.scenario         = idea;
            return tc;
        } catch(e) { return null; }
    },

    /**
     * Generate a complete dataset of test cases and persist them to the staging table.
     * @param {string} taskDescription
     * @param {Object} promptInputsSpec - { key: description }
     * @param {number} numCases
     * @returns {string} dataset_id (UUID)
     */
    generateDataset: function(taskDescription, promptInputsSpec, numCases) {
        var ideas = this.generateUniqueIdeas(taskDescription, promptInputsSpec, numCases || 3);
        var datasetId = this._uuid();

        for (var i = 0; i < ideas.length; i++) {
            var tc = this.generateTestCase(taskDescription, ideas[i], promptInputsSpec);
            if (!tc) { continue; }
            this._saveEvalCase({
                dataset_id:             datasetId,
                task_description:       taskDescription,
                scenario:               ideas[i],
                prompt_inputs_json:     JSON.stringify(tc.prompt_inputs     || {}),
                solution_criteria_json: JSON.stringify(tc.solution_criteria || [])
            });
        }

        return datasetId;
    },

    // ─── Grading ──────────────────────────────────────────────────────────────
    /**
     * Use Claude to grade a model output against a test case.
     * @param {Object} testCase    - { task_description, prompt_inputs, solution_criteria, scenario }
     * @param {string} output      - the model output to grade
     * @param {string} extraCriteria - additional mandatory requirements (or empty string)
     * @returns {Object}  - { score, reasoning, strengths, weaknesses }
     */
    gradeOutput: function(testCase, output, extraCriteria) {
        var connector = new x_146833_claudec_0.ClaudeConnector();

        var promptInputsStr = '';
        var inputs = testCase.prompt_inputs || {};
        for (var k in inputs) {
            if (inputs.hasOwnProperty(k)) {
                promptInputsStr += '"' + k + '":"' + String(inputs[k]).replace(/"/g, '\\"') + '",\n';
            }
        }

        var extraSection = '';
        if (extraCriteria) {
            extraSection = 'Mandatory Requirements — ANY VIOLATION = score of 3 or lower:\n<extra_important_criteria>\n' + extraCriteria + '\n</extra_important_criteria>\n\n';
        }

        var criteriaStr = (testCase.solution_criteria || []).join('\n');

        var evalPrompt = this.render(
            'Evaluate the following AI-generated solution with EXTREME RIGOR.\n\n' +
            'Task description:\n<task_description>\n{task_description}\n</task_description>\n\n' +
            'Task inputs:\n<task_inputs>\n{{ {prompt_inputs} }}\n</task_inputs>\n\n' +
            'Solution:\n<solution>\n{output}\n</solution>\n\n' +
            'Evaluation criteria:\n<criteria>\n{criteria}\n</criteria>\n\n' +
            '{extra_section}' +
            'Scoring: 1-3=fails mandatory, 4-6=meets mandatory with deficiencies, 7-8=meets most, 9-10=meets all.\n\n' +
            'Grade ONLY on listed criteria. Give 10 if all criteria are met.\n\n' +
            'Output JSON with keys: strengths (string[]), weaknesses (string[]), reasoning (string), score (number).',
            {
                task_description: testCase.task_description || '',
                prompt_inputs:    promptInputsStr,
                output:           output,
                criteria:         criteriaStr,
                extra_section:    extraSection
            }
        );

        var messages = [
            { role: 'user',      content: evalPrompt },
            { role: 'assistant', content: '```json' }
        ];

        var result = connector.chat(messages, {
            stop_sequences: ['```'],
            temperature:    0.0
        });

        if (!result.success) { return { score: 0, reasoning: result.error, strengths: [], weaknesses: [] }; }
        try { return JSON.parse(result.text); } catch(e) {
            return { score: 0, reasoning: 'Parse error: ' + e.toString(), strengths: [], weaknesses: [] };
        }
    },

    // ─── Full evaluation run ──────────────────────────────────────────────────
    /**
     * Run a user-supplied prompt function against all cases in a dataset,
     * grade each output, and persist results back to the eval_case table.
     * Since ServiceNow runs synchronously, this iterates cases sequentially.
     *
     * @param {string}   datasetId      - from generateDataset()
     * @param {string}   promptTemplate - template string with {key} placeholders
     * @param {string}   extraCriteria  - additional mandatory requirements (or '')
     * @returns {Object} - { run_id, average_score, pass_rate, cases: [...] }
     */
    runEvaluation: function(datasetId, promptTemplate, extraCriteria) {
        var connector = new x_146833_claudec_0.ClaudeConnector();
        var runId     = this._uuid();
        var cases     = this._loadDataset(datasetId);
        var results   = [];
        var totalScore = 0;
        var passed     = 0;

        for (var i = 0; i < cases.length; i++) {
            var tc = cases[i];

            // Render the prompt template using the test case's prompt_inputs
            var renderedPrompt = this.render(promptTemplate, tc.prompt_inputs || {});

            var chatMessages = [{ role: 'user', content: renderedPrompt }];
            var chatResult   = connector.chat(chatMessages, { temperature: 1.0 });
            var output       = chatResult.success ? chatResult.text : ('Error: ' + chatResult.error);

            // Grade
            var grade = this.gradeOutput(tc, output, extraCriteria || '');
            var score = grade.score || 0;

            totalScore += score;
            if (score >= 7) { passed += 1; }

            // Update the staging record
            this._updateEvalCase(tc.sys_id, {
                run_id:    runId,
                output:    output.substring(0, 8000),
                score:     score,
                reasoning: (grade.reasoning || '').substring(0, 2000)
            });

            results.push({
                sys_id:    tc.sys_id,
                scenario:  tc.scenario,
                score:     score,
                reasoning: grade.reasoning || '',
                output:    output
            });
        }

        var n = cases.length || 1;
        return {
            run_id:        runId,
            dataset_id:    datasetId,
            case_count:    cases.length,
            average_score: Math.round((totalScore / n) * 10) / 10,
            pass_rate:     Math.round((passed / n) * 1000) / 10,
            cases:         results
        };
    },

    // ─── Private helpers ──────────────────────────────────────────────────────
    _uuid: function() {
        return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(ch) {
            var r = Math.random() * 16 | 0;
            return (ch === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
        });
    },

    _saveEvalCase: function(fields) {
        var gr = new GlideRecord('x_146833_claudec_0_eval_case');
        gr.initialize();
        for (var f in fields) {
            if (fields.hasOwnProperty(f)) { gr.setValue(f, fields[f] || ''); }
        }
        gr.insert();
    },

    _updateEvalCase: function(sysId, fields) {
        if (!sysId) { return; }
        var gr = new GlideRecord('x_146833_claudec_0_eval_case');
        if (!gr.get(sysId)) { return; }
        for (var f in fields) {
            if (fields.hasOwnProperty(f)) { gr.setValue(f, fields[f]); }
        }
        gr.update();
    },

    _loadDataset: function(datasetId) {
        var records = [];
        var gr = new GlideRecord('x_146833_claudec_0_eval_case');
        gr.addQuery('dataset_id', datasetId);
        gr.orderBy('sys_created_on');
        gr.query();
        while (gr.next()) {
            var inputs   = {};
            var criteria = [];
            try { inputs   = JSON.parse(gr.getValue('prompt_inputs_json')     || '{}'); } catch(e) {}
            try { criteria = JSON.parse(gr.getValue('solution_criteria_json') || '[]'); } catch(e) {}
            records.push({
                sys_id:           gr.getUniqueValue(),
                dataset_id:       gr.getValue('dataset_id'),
                task_description: gr.getValue('task_description'),
                scenario:         gr.getValue('scenario'),
                prompt_inputs:    inputs,
                solution_criteria: criteria
            });
        }
        return records;
    },

    type: 'ClaudePromptEvaluator'
};
